import { expect, expectStatus, test } from "../../fixtures";

test("Signing out clears the session cookie", { tag: "@AUTH-06" }, async ({ apiAs }) => {
  // Arrange
  const member = await apiAs("member");

  // Act
  const response = await member.post("/api/auth/logout");

  // Assert
  await expectStatus(response, 204);
  const cookie = response.headersArray().find((h) => h.name.toLowerCase() === "set-cookie");
  const headers = JSON.stringify(response.headersArray());
  expect(cookie?.value, `Set-Cookie for session\n${headers}`).toMatch(/^session=(""|);/);
  expect(cookie?.value.toLowerCase(), `session cookie expires now\n${headers}`).toContain("max-age=0");
});
